/**
 * Seed the `acceptance-drain-sweep` routine — P-020 of
 * design-to-code-coverage-seam-2026-09-02 (handler in
 * `acceptance-drain-sweep-action.ts`; logic in
 * `../../agent-tools/plans/acceptance-drain-sweep.ts`'s
 * `runAcceptanceDrainSweepOnce`).
 *
 *   - `acceptance-drain-sweep` (every 6 h): for each plan held in
 *     `awaiting-acceptance`, run the real ship gate and file ONE claimable work
 *     item naming its actual first blocker, quoting the gate's own repair text.
 *
 *     This is the EXIT for a gate that had none. `plan-drain-sweep` (seeded
 *     alongside) pushes plans INTO `awaiting-acceptance` when their items drain;
 *     the ceremony that gets them out is seven steps long and its refusals were
 *     visible only to someone who explicitly attempted a ship. Measured over all
 *     187 held papercusp plans: 161 (86.1%) had never had `plans:audit` run even
 *     once, oldest 2026-06-04 (D-032). Same queue-not-wall pairing
 *     `spec-triad-sweep` already has, and the same standing mandate — it files
 *     claimable work rather than routing a decision to a person.
 *
 *     Bounded, idempotent, non-throwing. Bounded: `maxFilings` items per tick, so
 *     the accumulated backlog is filed over several ticks rather than 187 items
 *     in one pass. Idempotent: each filing claims a unique condition key and is
 *     refreshed by `payload.acceptanceDrainPlan` on every gate read, so a re-sweep
 *     updates the ledger in place without minting siblings. Bounded SELECTs +
 *     work-item writes only; spawns no agent, no LLM, no network.
 *
 *     Never advances a plan to `shipped` and never edits a plan body — it only
 *     files work. The ship gate needs a code-truth audit and independent
 *     acceptance grading that no sweep can evidence, and auto-shipping would
 *     forge exactly that evidence (the same rule `plan-drain-sweep` states as its
 *     D-005 point 6).
 *
 *     Deliberately does NOT file against rubric-template plans (exempt from
 *     carrying an acceptance rubric of their own — an infinite regress the gate
 *     itself excludes, so the item could never be completed) or scheduled-plan
 *     INSTANCES (auto-generated recurrences, not authored work).
 *
 * Flag-gated on `ACCEPTANCE_DRAIN_SWEEP` (default ON). It changes no gate verdict
 * and has no owner-authority, destructive or outward-facing effect — the only
 * thing it changes is whether anyone is TOLD — so it is seeded ACTIVE by default;
 * pass `--inactive` to seed dark.
 *
 *   tsx seed-acceptance-drain-sweep-routine.ts                   # seed ACTIVE (default)
 *   tsx seed-acceptance-drain-sweep-routine.ts --inactive        # seed dark
 *   tsx seed-acceptance-drain-sweep-routine.ts --max-filings 5   # smaller per-tick bound
 *
 * trigger_config knobs (optional, editable via the routines admin):
 *   - maxFilings (default 25, ACCEPTANCE_DRAIN_MAX_FILINGS_PER_RUN)
 *
 * Idempotent upsert on (install_slug, name), same key discipline as every routine
 * in this dir. A re-run does NOT live-arm an already-running host — the routine
 * engine (routinesTick) picks a freshly-seeded cron row up on its next tick.
 */
import { getOrgPg } from '@papercusp/db-org';
import { activeWorkspaceId } from '../../workspace-registry';
import { operatorHomeHarnessSlug } from '../operator-home-harness';

const SLUG = process.env.ACCEPTANCE_DRAIN_SWEEP_ROUTINE_SLUG ?? operatorHomeHarnessSlug();
/** Every 6 hours on the :00 second (6-field: sec min hour dom mon dow). A plan
 *  entering `awaiting-acceptance` has just had its LAST item finished, so nothing
 *  about it is urgent — the work it owes takes a human-scale session to do. At
 *  25 filings a tick this drains the measured 187-plan backlog in under two days
 *  and costs one bounded SELECT pair per tick thereafter. Deliberately slower than
 *  plan-drain-sweep's 30 min: that one only writes a status line, this one files
 *  work into a shared backlog, and over-filing a queue is its own harm. */
const CRON = '0 0 */6 * * *';

function argNumber(flag: string): number | undefined {
  const idx = process.argv.indexOf(flag);
  if (idx === -1) return undefined;
  const v = Number(process.argv[idx + 1]);
  return Number.isFinite(v) && v > 0 ? v : undefined;
}

async function main(): Promise<void> {
  const active = !process.argv.includes('--inactive');
  const maxFilings = argNumber('--max-filings');
  const ws = activeWorkspaceId();
  const { sql } = getOrgPg();
  const name = 'acceptance-drain-sweep';
  const id = `rt_${SLUG}_${name}`.replace(/[^a-z0-9_]/gi, '_').toLowerCase();
  const triggerConfig = {
    cron: CRON,
    ...(maxFilings ? { maxFilings } : {}),
  };
  await sql`
    INSERT INTO harness_shared.routines
      (id, install_slug, workspace_id, name, trigger_kind, trigger_config, target_role,
       concurrency, catchup, active, next_fire_at)
    VALUES (${id}, ${SLUG}, ${ws}, ${name}, 'cron', ${JSON.stringify(triggerConfig)}::text::jsonb,
            'system:acceptance-drain-sweep', 'skip', 'skip-old', ${active}, now())
    ON CONFLICT (install_slug, name) DO UPDATE SET
      target_role = EXCLUDED.target_role,
      trigger_config = EXCLUDED.trigger_config,
      -- active intentionally NOT re-applied on conflict (EI-19301170070808928): a
      -- re-seed must never clobber an operator's runtime pause/resume of this routine.
      workspace_id = EXCLUDED.workspace_id,
      updated_at = now()
  `;
  console.log(
    `[seed-acceptance-drain-sweep-routine] seeded "${name}" for "${SLUG}" (ws=${ws}, active=${active}) — ` +
      `6-hour sweep filing claimable work for plans the ship gate is holding` +
      (maxFilings ? `, maxFilings=${maxFilings}` : '') +
      '.',
  );
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error(
      '[seed-acceptance-drain-sweep-routine] FAILED:',
      e instanceof Error ? e.message : e,
    );
    process.exit(1);
  });

/**
 * Seed the `acceptance-grading-sweep` routine — the acceptance-grading stall
 * sweep's 600s cadence (acceptance-grading-stall-sweep-2026-08-26 P-004; handler in
 * `acceptance-grading-sweep-action.ts`, orchestration in
 * `../../acceptance-grading-sweep-run.ts`, decision core in
 * `../../acceptance-grading-sweep.ts`).
 *
 * A bespoke `tier:'ephemeral'` seed (interval_sec, NO cron, `next_fire_at = NULL`)
 * rather than a per-install blueprint `triggers.schedule` entry — the sweep is an
 * operator-HOME-level substrate concern (ONE bounded sweep serves every workspace's
 * plans), not a per-blueprint-install cadence, mirroring
 * `seed-consult-expiry-routine.ts`'s documented reasoning. Ephemeral rows are armed
 * by the per-host ephemeral executor (`../../dbos/ephemeral-executor.ts`) on boot —
 * NOT a bare `setInterval` (`lint:no-raw-setinterval`).
 *
 * 600s cadence: the decision core's own thresholds are 2h (re-dispatch) and 12h
 * (escalate), so a 10-minute sweep bounds detection overshoot at ~8% of the shortest
 * contract. The cadence is deliberately far below both thresholds so that sweep
 * TIMING can never be the thing that decides an outcome — the thresholds decide, and
 * the sweep merely observes often enough not to matter.
 *
 * SEEDED ACTIVE by default: the sweep is bounded on both axes (a scan cap and an
 * action cap per tick), it can only re-dispatch an idempotent grader resolve or mint
 * one condition-keyed work-item, and "finished work never ships dark" (root
 * CLAUDE.md). It cannot grade, score, record a verdict or alter a refusal code —
 * those capabilities are absent from its dependency interface, not merely unused.
 * Pass `--inactive` to seed dark instead.
 *
 *   tsx seed-acceptance-grading-sweep-routine.ts              # seed ACTIVE (default)
 *   tsx seed-acceptance-grading-sweep-routine.ts --inactive   # seed dark
 *
 * Idempotent (upsert on (install_slug, name), same key discipline as every routine
 * in this dir). A re-run does NOT live-arm a host that's already running (restart
 * papercup-bg-host to pick up a freshly-seeded row live).
 */
import { getOrgPg } from '@papercusp/db-org';
import { activeWorkspaceId } from '../../workspace-registry';
import { operatorHomeHarnessSlug } from '../operator-home-harness';

const SLUG = process.env.ACCEPTANCE_GRADING_SWEEP_ROUTINE_SLUG ?? operatorHomeHarnessSlug();
const NAME = 'acceptance-grading-sweep';
const TARGET_ROLE = 'system:acceptance-grading-sweep';
const DEFAULT_INTERVAL_SEC = 60;

async function main(): Promise<void> {
  const active = !process.argv.includes('--inactive');
  const ws = activeWorkspaceId();
  const { sql } = getOrgPg();
  const id = `rt_${SLUG}_${NAME}`.replace(/[^a-z0-9_]/gi, '_').toLowerCase();
  const triggerConfig = JSON.stringify({ interval_sec: DEFAULT_INTERVAL_SEC });
  await sql`
    INSERT INTO harness_shared.routines
      (id, install_slug, name, trigger_kind, trigger_config, target_role,
       concurrency, catchup, active, tier, next_fire_at, workspace_id)
    VALUES (
      ${id}, ${SLUG}, ${NAME}, 'cron',
      ${triggerConfig}::text::jsonb, ${TARGET_ROLE},
      'skip', 'skip-old', ${active}, 'ephemeral', NULL, ${ws}
    )
    ON CONFLICT (install_slug, name) DO UPDATE SET
      trigger_kind   = EXCLUDED.trigger_kind,
      trigger_config = EXCLUDED.trigger_config,
      target_role    = EXCLUDED.target_role,
      tier           = EXCLUDED.tier,
      -- active intentionally NOT re-applied on conflict (EI-19301170070808928): a
      -- re-seed must never clobber an operator's runtime pause/resume of this routine.
      workspace_id   = EXCLUDED.workspace_id,
      updated_at     = now()
  `;
  console.log(
    `[seed-acceptance-grading-sweep-routine] seeded "${NAME}" for "${SLUG}" (ws=${ws}, active=${active}, ` +
      `tier=ephemeral, interval=${DEFAULT_INTERVAL_SEC}s) — acceptance-grading stall sweep cadence. ` +
      (active
        ? 'Cadence seeded ACTIVE — restart papercusp-bg-host to live-arm on a host that was already up.'
        : 'Inactive — enable via the routines admin or re-run without --inactive.'),
  );
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error(
      '[seed-acceptance-grading-sweep-routine] FAILED:',
      e instanceof Error ? e.message : e,
    );
    process.exit(1);
  });

/**
 * Seed the `account-capacity-reprobe` routine — the scheduled walled-account re-probe's
 * 300s cadence (EI-21921833535413808; handler in `account-capacity-reprobe-action.ts`, logic
 * reused from `agent-tools/accounts/probe-capacity.ts`'s `runCapacityProbe`).
 *
 * A bespoke `tier:'ephemeral'` seed (interval_sec, NO cron, `next_fire_at = NULL`) rather than
 * a per-install blueprint `triggers.schedule` entry — the account pool is an operator-HOME-level
 * substrate concern (ONE bounded sweep serves every workspace's account rows), not a per-blueprint-
 * install cadence, mirroring `seed-consult-expiry-routine.ts`'s documented reasoning. Ephemeral
 * rows are armed by the per-host ephemeral executor (`../../dbos/ephemeral-executor.ts`) on boot —
 * NOT a bare `setInterval` (`lint:no-raw-setinterval`).
 *
 * 300s cadence: `walledOnly` bounds the per-tick cost to accounts already flagged full (typically
 * a handful across both providers), and each probe is "one minimal request" (a header read, not a
 * billed inference call) — so a 5-minute cadence recovers a false wall quickly without meaningfully
 * adding to upstream traffic. A genuinely-walled account is merely re-confirmed each tick (a 429
 * carries the true reset and changes nothing).
 *
 * SEEDED ACTIVE by default: the action is read-mostly (one probe request per already-walled
 * account) plus a narrowly-scoped write (the account-pool projection + gateway readmit) that only
 * ever CORRECTS a wall the account does not actually have — "finished work never ships dark" (root
 * CLAUDE.md). Pass `--inactive` to seed dark instead.
 *
 *   tsx seed-account-capacity-reprobe-routine.ts              # seed ACTIVE (default)
 *   tsx seed-account-capacity-reprobe-routine.ts --inactive   # seed dark
 *
 * Idempotent (upsert on (install_slug, name), same key discipline as every routine in this dir).
 * A re-run does NOT live-arm a host that's already running (restart papercup-bg-host to pick up a
 * freshly-seeded row live).
 */
