  console.log(
    `[seed-account-capacity-reprobe-routine] seeded "${NAME}" for "${SLUG}" (ws=${ws}, active=${active}, ` +
      `tier=ephemeral, interval=${DEFAULT_INTERVAL_SEC}s) — scheduled walled-account re-probe cadence. ` +
