/**
 * Seed the `bulk-run-watchdog` routine — the bulk-run stall sweep's 300s cadence
 * (autonomous-inbox-resolution-2026-08-31 P-002; handler in
 * `bulk-run-watchdog-action.ts`, decision core in
 * `../../attention/bulk-run-watchdog.ts`, DB halves in
 * `../../attention/bulk-run-store.ts`).
 *
 * A bespoke `tier:'ephemeral'` seed (interval_sec, NO cron, `next_fire_at = NULL`)
 * rather than a per-install blueprint `triggers.schedule` entry — one bounded sweep
 * serves every workspace's runs, mirroring `seed-acceptance-grading-sweep-routine.ts`'s
 * documented reasoning. Ephemeral rows are armed by the per-host ephemeral executor
 * (`../../dbos/ephemeral-executor.ts`) on boot — NOT a bare `setInterval`
 * (`lint:no-raw-setinterval`).
 *
 * 300s cadence: it matches the store's `RUN_HEARTBEAT_STALE_MS`, so a run is noticed
 * within roughly one staleness window of going stale. The cadence deliberately cannot
 * decide an outcome — `strandStaleRun` re-evaluates the staleness predicate INSIDE its
 * own UPDATE ... WHERE, so an early tick simply matches nothing and a late one changes
 * only how long the strand took to notice, never whether it was correct.
 *
 * SEEDED ACTIVE by default: the sweep's only writes are (a) failing a run that is
 * already provably stale, which `restartRun` explicitly accepts and can resume with
 * every decided outcome preserved, and (b) recomputing counters from the run's own
 * rows — a derivation, not a judgement. It cannot start a run, dispatch an agent,
 * apply a terminal action to any attention item, or touch an item that was already
 * decided; those capabilities are absent from its dependency interface, not merely
 * unused. And "finished work never ships dark" (root CLAUDE.md). Pass `--inactive`
 * to seed dark instead.
 *
 *   tsx seed-bulk-run-watchdog-routine.ts              # seed ACTIVE (default)
 *   tsx seed-bulk-run-watchdog-routine.ts --inactive   # seed dark
 *
 * Idempotent (upsert on (install_slug, name), same key discipline as every routine in
 * this dir). A re-run does NOT live-arm a host that's already running (restart
 * papercup-bg-host to pick up a freshly-seeded row live).
 */
import { getOrgPg } from '@papercusp/db-org';
import { activeWorkspaceId } from '../../workspace-registry';
import { operatorHomeHarnessSlug } from '../operator-home-harness';
import { BULK_RUN_WATCHDOG_INTERVAL_SEC } from './bulk-run-watchdog-action';

const SLUG = process.env.BULK_RUN_WATCHDOG_ROUTINE_SLUG ?? operatorHomeHarnessSlug();
const NAME = 'bulk-run-watchdog';
const TARGET_ROLE = 'system:bulk-run-watchdog';

async function main(): Promise<void> {
  const active = !process.argv.includes('--inactive');
  const ws = activeWorkspaceId();
  const { sql } = getOrgPg();
  const id = `rt_${SLUG}_${NAME}`.replace(/[^a-z0-9_]/gi, '_').toLowerCase();
  const triggerConfig = JSON.stringify({ interval_sec: BULK_RUN_WATCHDOG_INTERVAL_SEC });
  await sql`
    INSERT INTO harness_shared.routines
      (id, install_slug, name, trigger_kind, trigger_config, target_role,
       concurrency, catchup, active, tier, next_fire_at, workspace_id)
    VALUES (
      ${id}, ${SLUG}, ${NAME}, 'cron',
      ${triggerConfig}::text::jsonb, ${TARGET_ROLE},
      'skip', 'skip-old', ${active}, 'ephemeral', NULL, ${ws}
    )
    ON CONFLICT (install_slug, name) DO UPDATE SET
      trigger_kind   = EXCLUDED.trigger_kind,
      trigger_config = EXCLUDED.trigger_config,
      target_role    = EXCLUDED.target_role,
      tier           = EXCLUDED.tier,
      -- active intentionally NOT re-applied on conflict (EI-19301170070808928): a
      -- re-seed must never clobber an operator's runtime pause/resume of this routine.
      workspace_id   = EXCLUDED.workspace_id,
      updated_at     = now()
  `;
  console.log(
    `[seed-bulk-run-watchdog-routine] seeded "${NAME}" for "${SLUG}" (ws=${ws}, active=${active}, ` +
      `tier=ephemeral, interval=${BULK_RUN_WATCHDOG_INTERVAL_SEC}s) — bulk-run stall + counter-drift sweep. ` +
      (active
        ? 'Cadence seeded ACTIVE — restart papercusp-bg-host to live-arm on a host that was already up.'
        : 'Inactive — enable via the routines admin or re-run without --inactive.'),
  );
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error(
      '[seed-bulk-run-watchdog-routine] FAILED:',
      e instanceof Error ? e.message : e,
    );
    process.exit(1);
  });

/**
 * Seed the `cargo-test` routine (production-test-readiness-2026-07-06 P-009 /
 * WI-3206) — `system:cargo-test` → `cargo-test-action.ts`, which runs the desktop
 * shell's Rust/cargo native suite via `scripts/report-cargo-tests.mjs` and records
 * results into `harness_shared.test_runs` (framework='cargo').
 *
 * Hourly, offset from green-checkpoint (:15) and the doc-anchor reconcile /
 * session-dir-gc slots so it never contends with them for the same tick minute.
 *
 * Seeded ACTIVE by default: the action is read-only w.r.t. the repo (it only runs
 * `cargo test`, never mutates source) and self-gates to the operator-home
 * installSlug (a stray per-hive routine cleanly no-ops), so an active routine is
 * safe from the moment it exists — finished work never ships dark (CLAUDE.md).
 * `--inactive` seeds it off for an explicit dark launch.
 *
 *   tsx seed-cargo-test-routine.ts              # seed ACTIVE
 *   tsx seed-cargo-test-routine.ts --inactive    # seed off
 */
import { getOrgPg } from '@papercusp/db-org';
import { activeWorkspaceId } from '../../workspace-registry';
import { operatorHomeHarnessSlug } from '../operator-home-harness';

const SLUG = process.env.CARGO_TEST_ROUTINE_SLUG ?? operatorHomeHarnessSlug();
/** Hourly at :45 — offset from green-checkpoint (:15) and session-dir-gc/doc-anchor
 *  reconcile so this never contends with them for the same tick minute. */
const CRON = '0 45 * * * *';

async function main(): Promise<void> {
  const active = !process.argv.includes('--inactive');
  const ws = activeWorkspaceId();
  const { sql } = getOrgPg();
  const name = 'cargo-test';
  const id = `rt_${SLUG}_${name}`.replace(/[^a-z0-9_]/gi, '_').toLowerCase();
  await sql`
    INSERT INTO harness_shared.routines
      (id, install_slug, workspace_id, name, trigger_kind, trigger_config, target_role,
       concurrency, catchup, active, next_fire_at)
    VALUES (${id}, ${SLUG}, ${ws}, ${name}, 'cron', ${JSON.stringify({ cron: CRON })}::text::jsonb,
            'system:cargo-test', 'skip', 'skip-old', ${active}, now())
    ON CONFLICT (install_slug, name) DO UPDATE SET
      target_role = EXCLUDED.target_role,
      trigger_config = EXCLUDED.trigger_config,
      active = EXCLUDED.active,
      workspace_id = EXCLUDED.workspace_id,
      updated_at = now()
  `;
  console.log(
    `[seed-cargo-test-routine] seeded "${name}" for "${SLUG}" (ws=${ws}, active=${active}) — ` +
      `hourly (:45) cargo test run of papercusp-desktop/src-tauri, recorded as framework=cargo. ` +
      (active ? 'Cadence LIVE.' : 'Inactive — enable with --active or the routines admin.'),
  );
  await sql.end({ timeout: 5 });
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error('[seed-cargo-test-routine] FAILED:', e instanceof Error ? e.message : e);
    process.exit(1);
  });

/**
 * Seed the always-on post-close completion-claim recheck (WI-2142447).
 *
 * Cadence: every 6 hours at :25, off both the hourly :07 admission-delta sweep and the
 * daily 03:15 dead-citation sweep. More often than daily because the measured drift rate on
 * this tree is a 69-MINUTE half-life on a load-bearing claim about a named array
 * (EI-22175397357614106); less often than hourly because the pass reads and parses source
 * per claim, and a claim that went false four hours ago is not more wrong than one that
 * went false four minutes ago — nothing downstream reacts to it faster than a person reads.
 *
 *   tsx seed-completion-claim-recheck-routine.ts
 *   tsx seed-completion-claim-recheck-routine.ts --inactive
 */
import { getOrgPg } from '@papercusp/db-org';
import { activeWorkspaceId } from '../../workspace-registry';
import { operatorHomeHarnessSlug } from '../operator-home-harness';
import { COMPLETION_CLAIM_RECHECK } from './completion-claim-recheck-action';

const SLUG = process.env.COMPLETION_CLAIM_RECHECK_ROUTINE_SLUG ?? operatorHomeHarnessSlug();

async function main(): Promise<void> {
  const active = !process.argv.includes('--inactive');
  const { sql } = getOrgPg();
  const workspaceId = activeWorkspaceId();
  const name = COMPLETION_CLAIM_RECHECK;
  const id = `rt_${SLUG}_${name}`.replace(/[^a-z0-9_]/gi, '_').toLowerCase();
  const triggerConfig = { cron: '0 25 */6 * * *' };
  await sql`
    INSERT INTO harness_shared.routines
      (id, install_slug, workspace_id, name, trigger_kind, trigger_config, target_role,
       payload_template, concurrency, catchup, active, tier, next_fire_at)
    VALUES (${id}, ${SLUG}, ${workspaceId}, ${name}, 'cron',
            ${JSON.stringify(triggerConfig)}::text::jsonb, ${`system:${name}`},
            ${'{}'}::text::jsonb, 'skip', 'skip-old',
            ${active}, 'durable', now())
    ON CONFLICT (install_slug, name) DO UPDATE SET
      target_role = EXCLUDED.target_role,
      trigger_config = EXCLUDED.trigger_config,
      tier = EXCLUDED.tier,
      workspace_id = EXCLUDED.workspace_id,
      updated_at = now()`;
  console.log(
    `[seed-completion-claim-recheck-routine] ${SLUG}: seeded durable 6-hourly :25 ` +
      `completion-claim recheck (${active ? 'ACTIVE' : 'inactive'}).`,
  );
  await sql.end({ timeout: 5 });
}

main()
  .then(() => process.exit(0))
  .catch((error) => {
    console.error(
      '[seed-completion-claim-recheck-routine] FAILED:',
      error instanceof Error ? error.message : error,
    );
    process.exit(1);
  });

/**
 * Seed the `consult-expiry-sweep` routine — the consult lifecycle expiry sweep's
 * 300s cadence (get-feedback-relevance-consults-2026-08-16 P-005 / D-005; handler
 * in `consult-expiry-action.ts`, logic in `../../consult/consult-expiry-core.ts`).
